package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.repository.*; import com.sunrise.dentalclinic.service.DashboardService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.*;
@Controller public class HomeController {private final DashboardService dashboard;private final AppointmentRepository appointments;public HomeController(DashboardService d,AppointmentRepository a){dashboard=d;appointments=a;}
 @GetMapping("/") String home(){return "redirect:/dashboard";} @GetMapping("/login") String login(){return "login";} @GetMapping("/access-denied") String denied(){return "access-denied";} @GetMapping("/help") String help(){return "help";}
 @GetMapping("/dashboard") String dashboard(Model m){var today=LocalDate.now(ZoneId.of("Asia/Colombo"));m.addAttribute("summary",dashboard.summary());m.addAttribute("today",appointments.findByAppointmentDateOrderByAppointmentTime(today));m.addAttribute("upcoming",appointments.findByAppointmentDateGreaterThanEqualOrderByAppointmentDateAscAppointmentTimeAsc(today.plusDays(1)).stream().limit(10).toList());return "dashboard";}}
